fun pop(n: Int, word: String): List<Long> {
    if (data.size < n) fault(word, "stack underflow", -4)
    val result = data.takeLast(n)
    repeat(n) {
        data.removeAt(data.lastIndex)
    }
    return result
fun address(n: Long, word: String): Int {
    return (n / 8).toInt()
